    internal static FrameworkElement Vector(string data, Brush brush, double size = 20) =>
        new Viewbox { Width = size, Height = size, Child = new System.Windows.Shapes.Path
        { Data = Geometry.Parse(data), Fill = brush, Stretch = Stretch.Uniform } };

    internal static FrameworkElement Coin(string asset, double size = 32)
    {
        string symbol = asset.ToLowerInvariant();
        if (symbol is not ("btc" or "eth" or "usdt" or "usdc" or "sol" or "doge" or "ltc" or "bnb" or "link" or "trx" or "dai"))
            return new TextBlock { Text = asset, Width = size, VerticalAlignment = VerticalAlignment.Center };
        return new Image { Width = size, Height = size, Source = new BitmapImage(
            new Uri($"pack://application:,,,/Assets/Support/{symbol}.png")), Stretch = Stretch.Uniform };
    }
